(()=>{const name=document.querySelector('#product-name'),slug=document.querySelector('#product-slug'),sku=document.querySelector('#base-sku');if(!name||!slug||!sku)return;const slugify=value=>value.toLowerCase().trim().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,120);const makeSku=value=>{const code=slugify(value).toUpperCase();return code?`TB-${code}`:''};let slugManual=slug.value.trim()!=='';let skuManual=sku.value.trim()!=='';slug.addEventListener('input',()=>slugManual=true);sku.addEventListener('input',()=>skuManual=true);name.addEventListener('input',()=>{if(!slugManual)slug.value=slugify(name.value);if(!skuManual)sku.value=makeSku(name.value)});slug.addEventListener('blur',()=>{if(!slug.value.trim()){slugManual=false;slug.value=slugify(name.value)}});sku.addEventListener('blur',()=>{if(!sku.value.trim()){skuManual=false;sku.value=makeSku(name.value)}});if(!slugManual)slug.value=slugify(name.value);if(!skuManual)sku.value=makeSku(name.value)})();
(()=>{const editor=document.querySelector('[data-product-editor]'),list=document.querySelector('#variant-list'),add=document.querySelector('#add-variant'),empty=document.querySelector('#variant-empty'),tpl=document.querySelector('#variant-template'),sizeTpl=document.querySelector('#size-row-template');if(!editor)return;const toggleControls=(selector,disabled)=>editor.querySelectorAll(`${selector} input,${selector} select,${selector} textarea`).forEach(control=>control.disabled=disabled);const setType=()=>{const type=editor.querySelector('[name="product_type"]:checked')?.value||'single';editor.classList.toggle('product-type-variant',type==='variant');editor.classList.toggle('product-type-single',type==='single');toggleControls('.single-only',type==='variant');toggleControls('.variant-panel',type==='single')};editor.querySelectorAll('[name="product_type"]').forEach(input=>input.addEventListener('change',setType));setType();if(!list||!add)return;let index=list.querySelectorAll('[name^="variants["]').length;const money=value=>{const number=Number(value);return Number.isFinite(number)&&number>0?`PKR ${number.toLocaleString()}`:''};const slug=value=>value.trim().toUpperCase().replace(/[^A-Z0-9]+/g,'-').replace(/^-+|-+$/g,'');const bind=card=>{const color=card.querySelector('[data-variant-color]'),size=card.querySelector('[data-variant-size]'),sku=card.querySelector('[data-variant-sku]'),regular=card.querySelector('[data-regular-price]'),sale=card.querySelector('[data-sale-price]'),preview=card.querySelector('[data-price-preview]');let skuManual=sku.value.trim()!=='';const baseSku=()=>{const base=(document.querySelector('#base-sku')?.value||'TB').replace(/-+$/,'');return `${base}-${[color.value,size.value].filter(Boolean).map(slug).join('-')}`.replace(/-+$/,'')};const updateSku=()=>{if(!skuManual)sku.value=baseSku()};const updatePrice=()=>{const full=money(regular.value),offer=Number(sale.value);preview.innerHTML=offer>0&&offer<Number(regular.value)?`<s>${full}</s><strong>${money(offer)}</strong>`:`<strong>${full}</strong>`};color.addEventListener('input',updateSku);size.addEventListener('input',updateSku);sku.addEventListener('input',()=>skuManual=true);regular.addEventListener('input',updatePrice);sale.addEventListener('input',updatePrice);card.querySelector('.remove-variant').addEventListener('click',()=>{card.remove();empty.hidden=list.children.length>0});card.querySelector('.add-size').addEventListener('click',()=>{const row=sizeTpl.content.firstElementChild.cloneNode(true),rowIndex=index++;const source=name=>card.querySelector(`[name$="[${name}]"]`)?.value||'';row.querySelectorAll('[data-copy]').forEach(input=>{input.name=`variants[${rowIndex}][${input.dataset.copy}]`;input.value=source(input.dataset.copy)});row.querySelectorAll('[data-field]').forEach(input=>input.name=`variants[${rowIndex}][${input.dataset.field}]`);const rowSize=row.querySelector('[data-field="size"]'),rowSku=row.querySelector('[data-field="sku"]');const updateRowSku=()=>rowSku.value=`${(document.querySelector('#base-sku')?.value||'TB').replace(/-+$/,'')}-${slug(color.value)}-${slug(rowSize.value)}`.replace(/-+$/,'');rowSize.addEventListener('input',updateRowSku);row.querySelector('.remove-size').addEventListener('click',()=>row.remove());card.querySelector('[data-size-rows]').append(row);rowSize.focus();window.renderAdminIcons?.()});updatePrice()};list.querySelectorAll('.variant-card').forEach(bind);add.addEventListener('click',()=>{const card=tpl.content.firstElementChild.cloneNode(true),cardIndex=index++;card.querySelectorAll('[data-name]').forEach(input=>input.name=`variants[${cardIndex}][${input.dataset.name}]`);bind(card);list.append(card);empty.hidden=true;window.renderAdminIcons?.()})})();
(()=>{const editor=document.querySelector('[data-product-editor]');if(!editor)return;const sync=()=>{const single=editor.querySelector('[name="product_type"]:checked')?.value==='single';editor.querySelectorAll('.variant-only input,.variant-only select,.variant-only textarea').forEach(field=>field.disabled=single)};editor.querySelectorAll('[name="product_type"]').forEach(field=>field.addEventListener('change',sync));sync()})();
document.querySelector('[data-product-editor]')?.addEventListener('submit',event=>{event.currentTarget.querySelectorAll('.size-stock-row').forEach(row=>{const card=row.closest('.variant-card');row.querySelectorAll('[data-copy]').forEach(input=>input.value=card.querySelector(`[name$="[${input.dataset.copy}]"]`)?.value||'')})});
(()=>{const list=document.querySelector('#variant-list'),add=document.querySelector('#add-variant'),expandAll=document.querySelector('#expand-all-variants');if(!list||!add||!expandAll)return;const cards=()=>[...list.querySelectorAll('.variant-card')];const closeOthers=current=>{if(expandAll.checked)return;cards().forEach(card=>card.classList.toggle('is-expanded',card===current))};const bind=card=>{if(card.dataset.accordionBound)return;card.dataset.accordionBound='1';const header=card.querySelector(':scope > header'),title=header.querySelector('span'),color=card.querySelector('[data-variant-color]'),swatch=card.querySelector('input[type="color"]');const summary=document.createElement('span');summary.className='variant-summary';summary.innerHTML='<i class="variant-summary-swatch"></i><b></b>';title.prepend(summary);const update=()=>{summary.querySelector('b').textContent=color.value.trim()||'New colour';summary.querySelector('i').style.background=swatch.value||'#777777'};color.addEventListener('input',update);swatch.addEventListener('input',update);header.addEventListener('click',event=>{if(event.target.closest('button,input,label'))return;if(expandAll.checked)return;const opening=!card.classList.contains('is-expanded');cards().forEach(item=>item.classList.remove('is-expanded'));if(opening)card.classList.add('is-expanded')});update()};cards().forEach((card,index)=>{bind(card);card.classList.toggle('is-expanded',index===0)});add.addEventListener('click',()=>{const card=cards().at(-1);if(!card)return;bind(card);closeOthers(card);card.scrollIntoView({behavior:'smooth',block:'nearest'})});expandAll.addEventListener('change',()=>{if(expandAll.checked)cards().forEach(card=>card.classList.add('is-expanded'));else if(cards().length)closeOthers(cards()[0])})})();
document.querySelector('#add-variant')?.addEventListener('click',()=>{if(document.querySelector('#expand-all-variants')?.checked)document.querySelector('#variant-list .variant-card:last-child')?.classList.add('is-expanded')});
(()=>{const list=document.querySelector('#variant-list');if(!list)return;const initialise=card=>{const size=card.querySelector('[data-variant-size]');card.classList.toggle('has-sizes',Boolean(size?.value.trim()||card.querySelector('[data-size-rows]')?.children.length))};list.querySelectorAll('.variant-card').forEach(initialise);document.querySelector('#add-variant')?.addEventListener('click',()=>{const card=list.querySelector('.variant-card:last-child');if(card)initialise(card)});list.addEventListener('click',event=>{const button=event.target.closest('.add-size');if(!button)return;const card=button.closest('.variant-card');if(card.classList.contains('has-sizes'))return;event.preventDefault();event.stopImmediatePropagation();card.classList.add('has-sizes');card.querySelector('[data-variant-size]')?.focus()},true)})();
(()=>{const list=document.querySelector('#variant-list'),add=document.querySelector('#add-variant');if(!list)return;const money=value=>`PKR ${Number(value).toLocaleString()}`;const update=card=>{const full=card.querySelector('[data-regular-price]'),sale=card.querySelector('[data-sale-price]'),preview=card.querySelector('[data-price-preview]');if(!full||!sale||!preview)return;full.required=false;const fullValue=Number(full.value),saleValue=Number(sale.value);preview.innerHTML=saleValue>0&&fullValue>saleValue?`<s>${money(fullValue)}</s><strong>${money(saleValue)}</strong>`:saleValue>0?`<strong>${money(saleValue)}</strong>`:fullValue>0?`<strong>${money(fullValue)}</strong>`:''};const bind=card=>{if(card.dataset.optionalPriceBound)return;card.dataset.optionalPriceBound='1';card.querySelectorAll('[data-regular-price],[data-sale-price]').forEach(input=>input.addEventListener('input',()=>update(card)));update(card)};list.querySelectorAll('.variant-card').forEach(bind);add?.addEventListener('click',()=>{const card=list.querySelector('.variant-card:last-child');if(card)bind(card)})})();
(()=>{const list=document.querySelector('#variant-list'),addVariant=document.querySelector('#add-variant');if(!list)return;const arrange=card=>{const grid=card.querySelector('.variant-grid'),section=card.querySelector('.size-inventory'),firstRow=section?.querySelector(':scope > .size-stock-row'),size=firstRow?.querySelector('[data-variant-size]')?.closest('label'),stock=firstRow?.querySelector('[name$="[stock]"]')?.closest('label')||grid.querySelector(':scope > .colour-stock-field'),sku=card.querySelector('[data-variant-sku]')?.closest('label'),enabled=firstRow?.querySelector(':scope > .check-card')||grid.querySelector(':scope > .variant-enabled-field'),addSize=card.querySelector('.add-size');if(!grid||!section||!firstRow||!stock||!sku||!enabled||!addSize)return;sku.classList.add('variant-sku-field');enabled.classList.add('variant-enabled-field');stock.classList.add('colour-stock-field');grid.insertBefore(sku,section);grid.insertBefore(enabled,section);let action=grid.querySelector(':scope > .variant-size-action');if(!action){action=document.createElement('div');action.className='variant-size-action wide';grid.insertBefore(action,section)}action.append(addSize);if(card.classList.contains('has-sizes')){firstRow.insertBefore(size,firstRow.firstChild);firstRow.insertBefore(stock,size.nextSibling)}else{grid.insertBefore(stock,sku);section.hidden=true}section.hidden=!card.classList.contains('has-sizes')};const observe=card=>{if(card.dataset.inventoryLayoutBound)return;card.dataset.inventoryLayoutBound='1';arrange(card);new MutationObserver(()=>arrange(card)).observe(card,{attributes:true,attributeFilter:['class']})};list.querySelectorAll('.variant-card').forEach(observe);addVariant?.addEventListener('click',()=>{const card=list.querySelector('.variant-card:last-child');if(card)observe(card)});new MutationObserver(records=>records.forEach(record=>record.addedNodes.forEach(node=>{if(node.nodeType===1&&node.matches?.('.variant-card'))observe(node)}))).observe(list,{childList:true})})();
(()=>{let timer;document.addEventListener('input',event=>{const input=event.target.closest('[data-vendor-code]');if(!input)return;clearTimeout(timer);const status=input.parentElement.querySelector('[data-vendor-status]');status.textContent='';status.className='vendor-code-status';if(!input.value.trim())return;timer=setTimeout(async()=>{const params=new URLSearchParams({code:input.value.trim(),exclude_product_id:input.dataset.excludeProduct||'',exclude_variant_id:input.dataset.excludeVariant||''});const result=await fetch(`{{ route('admin.vendor-code.check') }}?${params}`,{headers:{Accept:'application/json'}}).then(response=>response.json());if(result.exists){status.classList.add('is-error');status.innerHTML=`Already used by <a href="${result.url}">${result.name}</a>`}else{status.classList.add('is-ok');status.textContent='Vendor code is available'}},350)})})();
